/** 频道/工具名 → 品牌 key；未知返回 null（调用方回退通用图标） */
export function brandKey(name = ""): string | null {
  const n = name.toLowerCase();
  // 顺序敏感：企业微信/企微 必须先于 微信，否则被 微信 抢先命中
  if (n.includes("企业微信") || n.includes("企微") || n.includes("wecom") || n.includes("wechat work")) return "wecom";
  if (n.includes("钉钉") || n.includes("dingtalk")) return "dingtalk";
  if (n.includes("飞书") || n.includes("feishu") || n.includes("lark")) return "feishu";
  if (n.includes("telegram")) return "telegram";
  if (n.includes("discord")) return "discord";
  if (n.includes("slack")) return "slack";
  if (n.includes("微信") || n.includes("wechat")) return "wechat";
  return null;
}
